"""Full-methods flow chart (figures/fig0_methods.png/.pdf): every stage from the chart to the audience models."""
import sys; TALK=len(sys.argv)>1 and sys.argv[1]=='talk'
import matplotlib; matplotlib.use('Agg'); import matplotlib.pyplot as plt; from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
plt.rcParams.update({'font.family':'serif','font.serif':['Liberation Serif','Times New Roman','DejaVu Serif'],'pdf.fonttype':42})
INK,INK2,BLUE,ORANGE,GRAY='#0b0b0b','#52514e','#2a78d6','#eb6834','#9a9992'
fig,ax=plt.subplots(figsize=(12,8.2)); ax.set_xlim(0,12); ax.set_ylim(0,8.2); ax.axis('off')
def box(x,y,w,h,title,body,edge=GRAY,fill='white',fs=10,bfs=8.4):
    ax.add_patch(FancyBboxPatch((x,y),w,h,boxstyle='round,pad=0.02,rounding_size=0.1',linewidth=1.3,edgecolor=edge,facecolor=fill))
    ax.text(x+w/2,y+h-0.24,title,ha='center',va='center',fontsize=fs,fontweight='bold',color=INK); ax.text(x+w/2,y+(h-0.3)/2-0.02,body,ha='center',va='center',fontsize=bfs,color=INK2,linespacing=1.3)
def arr(x1,y1,x2,y2,color=GRAY): ax.add_patch(FancyArrowPatch((x1,y1),(x2,y2),arrowstyle='-|>',mutation_scale=12,linewidth=1.2,color=color,shrinkA=2,shrinkB=2))
def stage(x,label): ax.text(x,7.95,label,ha='center',va='center',fontsize=10.5,fontweight='bold',color=INK)
# ---- stage 1 corpus (column x 0.3..2.5)
stage(1.4,'1  Corpus'); box(0.3,6.1,2.2,1.5,'Frame','Apple Podcasts US Politics\nchart, 13 July 2026\n250 shows'); arr(1.4,6.1,1.4,5.75)
box(0.3,4.35,2.2,1.4,'Inclusion rules','feed reachable, has audio,\nUS politics, ≥10 hours\n→ 219; 15 by recorded\ndecision → 204'); arr(1.4,4.35,1.4,4.0)
box(0.3,2.55,2.2,1.45,'Episode sample','census before 2018;\nladder of k per show per\nquarter (1,2,5,10,15,20,30)\n→ 31,191 episodes'); arr(1.4,2.55,1.4,2.2)
box(0.3,0.75,2.2,1.45,'Transcription','faster-whisper\nlarge-v3-turbo, GPU;\n25,900 hours; show-level\nscores for 194 shows')
# ---- stage 2 measures (x 3.1..5.6)
stage(4.35,'2  Measures of the talk')
box(3.1,5.55,2.5,2.05,'Listener-directed address','Multi-Feature Tagger of\nEnglish on 45,192 episodes:\ncommands (VIMP) and "you"\n(PP2) per 10,000 words;\nword-weighted show means;\nz-scored on 194 shows',edge=BLUE)
box(3.1,3.2,2.5,2.05,'One-sidedness','152,152 passages of 750\ncharacters, 40 per show-\nquarter; two-stage LLM rubric\n(political? then 7-point lean);\nshare of political words that\ntake a side; plus side score',edge=ORANGE)
box(3.1,0.75,2.5,2.15,'Validation and stability','side vs DIME donations (r .68),\nBrookings labels (22/24),\nlisteners\' party (r .92);\naddress: ICC .49, no drift,\nno event reaction, topics;\npassage-level r −.01',bfs=8.1)
arr(2.5,1.6,3.1,4.2,ORANGE); arr(2.5,1.7,3.1,6.5,BLUE)
arr(4.35,5.55,4.35,5.25,GRAY); arr(4.35,3.2,4.35,2.9,GRAY)
# ---- stage 3 audiences (x 6.2..8.7)
stage(7.45,'3  Audiences')
box(6.2,5.55,2.5,2.05,'Kettering–Gallup survey','Democracy for All, two waves\n(n 20,338 and 23,683);\nrespondents name their own\nsources; one matching rule:\ntitle, variant, or unique host\n→ 1,247 listeners / 64 shows')
box(6.2,3.2,2.5,2.05,'Exposure and controls','exposure = mean address (and\none-sidedness) of shows named;\ncontrols: party, attention, age,\neducation, lean of shows named,\nsurvey year')
box(6.2,0.75,2.5,2.15,'Inference','OLS clustered by show;\nCR2 with Satterthwaite df and\nwild cluster bootstrap;\nleave-one-show-out, permutation,\neach year alone;\nBenjamini–Hochberg q<.10 in scans',bfs=8.1)
arr(5.6,6.5,6.2,6.5,BLUE); arr(5.6,4.2,6.2,4.2,ORANGE); arr(7.45,5.55,7.45,5.25); arr(7.45,3.2,7.45,2.9)
# ---- stage 4 checks and results (x 9.3..11.7)
stage(10.5,'4  Checks and results')
box(9.3,5.55,2.4,2.05,'Independent checks','Pew ATP March 2025: regular\naudiences of 30 named sources;\nPew ATP Dec 2022: podcast\nlistened to most;\nApple reviews: 16,434 across\n141 shows, reading grade',bfs=8.1)
box(9.3,3.2,2.4,2.05,'Style → who listens','audiences of address-heavy\nshows look like the public on\neducation; threshold, both\nsides, net of one-sidedness;\nreplicates in all four sources',edge=BLUE,fill='#eef4fc')
box(9.3,0.75,2.4,2.15,'Style → cynicism','listeners of address-heavy\nshows are more cynical about\ninstitutions in the Year 1\nsurvey, net of one-sidedness',edge=ORANGE,fill='#fdf0ea',bfs=8.4) if TALK else box(9.3,0.75,2.4,2.15,'Stance → what is believed','election distrust follows\none-sidedness in both years;\naddress adds nothing net of it;\nYear 1 cynicism result for\naddress preliminary, untested\nin Year 2',edge=ORANGE,fill='#fdf0ea',bfs=8.1)
arr(8.7,6.5,9.3,6.5); arr(8.7,4.2,9.3,4.2,BLUE); arr(8.7,1.8,9.3,1.8,BLUE if TALK else ORANGE); arr(10.5,5.55,10.5,5.25)
name='figures/fig0_methods_talk' if TALK else 'figures/fig0_methods'; fig.savefig(name+'.png',dpi=300,bbox_inches='tight'); fig.savefig(name+'.pdf',bbox_inches='tight'); print('saved',name)
